    return '${planet}-ന് ഏറ്റവും കൂടുതൽ പോയിന്റുകളുണ്ട്, അതിനാൽ അതിന്റെ സൂചനകൾ നിങ്ങളുടെ ജീവിതത്തിൽ നന്നായി പിന്തുണയ്ക്കപ്പെടുന്നു.';
  }

  @override
