    return '${planet}-ന് ഏറ്റവും കുറഞ്ഞ പോയിന്റുകളുണ്ട്, പരിഹാരങ്ങളിൽ നിന്നും ബോധപൂർവമായ ശ്രമങ്ങളിൽ നിന്നും ഏറ്റവും കൂടുതൽ പ്രയോജനം നേടുന്നു.';
  }

